//! Cargo-driven `windowscodecs.dll` link, generated by tools/cargo_cell_gen.py
//! from the cmake link it replaces.
//! The module is C, compiled and linked by reactos-link: there is no Rust body.

use reactos_link::{Linker, ModuleKind, MsvcrtexKind};
use std::env;

fn main() {
    let arch = env::var("CARGO_CFG_TARGET_ARCH").expect("CARGO_CFG_TARGET_ARCH");
    let (target_json, entry, image_base) = match arch.as_str() {
        "x86" => ("i686-pc-windows-gnu", "_DllMainCRTStartup@12", Some(0x6cd80000u64)),
        "x86_64" => ("x86_64-pc-windows-gnu", "DllMainCRTStartup", Some(0x7fe51000000u64)),
        "aarch64" => ("aarch64-pc-windows-gnullvm", "DllMainCRTStartup", Some(0x7fe51000000u64)),
        o => panic!("windowscodecs-cargo: unsupported arch {o}"),
    };

    let link_order: &[&str] = match arch.as_str() {
        "x86" => &["dll/win32/windowscodecs/windowscodecs_wincodec_r.o", "engine:wine", "engine:uuid", "engine:pseh", "engine:oldnames", "import:libjpeg", "import:libpng", "import:libtiff", "import:ole32", "import:oleaut32", "import:rpcrt4", "import:shlwapi", "import:user32", "import:gdi32", "import:advapi32", "import:advapi32_vista", "import:propsys", "import:msvcrt", "import:kernel32", "import:ntdll", "engine:chkstk", "body"],
        "x86_64" => &["dll/win32/windowscodecs/windowscodecs_wincodec_r.o", "engine:wine", "engine:uuid", "engine:pseh", "engine:oldnames", "import:libjpeg", "import:libpng", "import:libtiff", "import:ole32", "import:oleaut32", "import:rpcrt4", "import:shlwapi", "import:user32", "import:gdi32", "import:advapi32", "import:advapi32_vista", "import:propsys", "import:msvcrt", "import:kernel32", "import:ntdll", "body"],
        "aarch64" => &["dll/win32/windowscodecs/windowscodecs_wincodec_r.o", "engine:wine", "engine:uuid", "engine:pseh", "engine:oldnames", "import:libjpeg", "import:libpng", "import:libtiff", "import:ole32", "import:oleaut32", "import:rpcrt4", "import:shlwapi", "import:user32", "import:gdi32", "import:advapi32", "import:advapi32_vista", "import:propsys", "import:msvcrt", "import:kernel32", "import:ntdll", "engine:chkstk", "body"],
        _ => unreachable!(),
    };

    // The module's part of cmake's windres command; reactos-link adds what every
    // module shares from reactos-link/cflags/rc.<arch>.flags (Linker::rc).
    let rc_includes: &[&str] = &[
        "@build/dll/win32/windowscodecs",
        "dll/win32/windowscodecs",
        "@build/sdk/include/wine",
        "sdk/include/wine",
        "@std",
        "vendor/opengl-headers/include",
        "vendor/libdxg/include",
        "vendor/libjpeg/include",
        "vendor/libpng/include",
        "sdk/lib/pseh/include",
        "vendor/zlib/include",
        "vendor/libtiff/include",
        "sdk/lib/tdilib",
    ];
    let rc_flags: &[&str] = &[];
    let rc_defines: &[&str] = &[
        "ENTRY_PREFIX=WIC_",
        "PROXY_DELEGATION",
        "WINE_REGISTER_DLL",
        "WINVER=0x502",
        "_CRT_DECLARE_NONSTDC_NAMES=1",
        "_CRT_NONSTDC_NO_DEPRECATE",
        "_DLL",
        "_WIN32_WINNT=0x600",
        "__USE_CRTIMP",
        "__WINESRC__",
    ];

    Linker::new(target_json)
        .c_from_compile_db("windowscodecs_shims", &["dll/win32/windowscodecs/bmpdecode.c", "dll/win32/windowscodecs/bmpencode.c", "dll/win32/windowscodecs/clipper.c", "dll/win32/windowscodecs/clsfactory.c", "dll/win32/windowscodecs/colorcontext.c", "dll/win32/windowscodecs/colortransform.c", "dll/win32/windowscodecs/converter.c", "dll/win32/windowscodecs/ddsformat.c", "dll/win32/windowscodecs/decoder.c", "dll/win32/windowscodecs/encoder.c", "dll/win32/windowscodecs/fliprotate.c", "dll/win32/windowscodecs/gifformat.c", "dll/win32/windowscodecs/icoformat.c", "dll/win32/windowscodecs/imgfactory.c", "dll/win32/windowscodecs/info.c", "dll/win32/windowscodecs/libjpeg.c", "dll/win32/windowscodecs/libpng.c", "dll/win32/windowscodecs/libtiff.c", "dll/win32/windowscodecs/main.c", "dll/win32/windowscodecs/metadatahandler.c", "dll/win32/windowscodecs/metadataquery.c", "dll/win32/windowscodecs/palette.c", "dll/win32/windowscodecs/pngformat.c", "dll/win32/windowscodecs/propertybag.c", "dll/win32/windowscodecs/proxy.c", "dll/win32/windowscodecs/regsvr.c", "dll/win32/windowscodecs/scaler.c", "dll/win32/windowscodecs/stream.c", "dll/win32/windowscodecs/tgaformat.c", "dll/win32/windowscodecs/ungif.c", "dll/win32/windowscodecs/uuid.c", "dll/win32/windowscodecs/wincodecs_common.c", "dll/win32/windowscodecs/bitmap.c", "dll/win32/windowscodecs/guid.c", "dll/win32/windowscodecs/proxy.dlldata.c", "dll/win32/windowscodecs/windowscodecs_wincodec_p.c"])
        .rc("dll/win32/windowscodecs/version.rc", rc_includes, rc_flags, rc_defines)
        .spec2def("dll/win32/windowscodecs/windowscodecs.spec", "windowscodecs.dll")
        .spec_stubs()
        .import_lib("vendor/libjpeg/libjpeg.spec", "libjpeg.dll", "libjpeg")
        .import_lib("vendor/libpng/libpng.spec", "libpng.dll", "libpng")
        .import_lib("vendor/libtiff/libtiff.spec", "libtiff.dll", "libtiff")
        .import_lib("dll/win32/ole32/ole32.spec", "ole32.dll", "ole32")
        .import_lib("dll/win32/oleaut32/oleaut32.spec", "oleaut32.dll", "oleaut32")
        .import_lib("dll/win32/rpcrt4/rpcrt4.spec", "rpcrt4.dll", "rpcrt4")
        .import_lib("dll/win32/shlwapi/shlwapi.spec", "shlwapi.dll", "shlwapi")
        .import_lib("win32ss/user/user32/user32.spec", "user32.dll", "user32")
        .import_lib("win32ss/gdi/gdi32/gdi32.spec", "gdi32.dll", "gdi32")
        .import_lib("dll/win32/advapi32/advapi32.spec", "advapi32.dll", "advapi32")
        .import_lib("dll/win32/advapi32_vista/advapi32_vista.spec", "advapi32_vista.dll", "advapi32_vista")
        .import_lib("dll/win32/propsys/propsys.spec", "propsys.dll", "propsys")
        .import_lib("dll/win32/msvcrt/msvcrt.spec", "msvcrt.dll", "msvcrt")
        .import_lib("dll/win32/kernel32/kernel32.spec", "kernel32.dll", "kernel32")
        .import_lib("dll/ntdll/def/ntdll.spec", "ntdll.dll", "ntdll")
        // The body, import libs and static libs in cmake's link order: the first
        // to define a symbol wins. cmake-built ones are reused until each has a
        // cargo home; `engine:` ones reactos-link builds.
        .link_order(link_order)
        .msvcrtex_crt(MsvcrtexKind::Dll)
        .link(ModuleKind::Win32Dll {
            entry: entry.into(),
            image_base,
            subsystem: None,
        });
}
